class University {}
class Department {}
class ResearchGroup {
  + groupName : string
}
class Researcher {
  + researcherId : int
  + name : string
}
class Project {
  + projectId : int
  + title : string
}
class WorkPackage {
  + wpId : int
  + description : string
}

University "1" *-- "1..*" Department
Department "1" -- "1..*" ResearchGroup
ResearchGroup "1" -- "1..*" Researcher
